export function formatClock(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
}

export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.drillGain = null;
    this.drillOsc = null;
    this.drillNoiseGain = null;
    this.windGain = null;
    this.muted = false;
    this.ready = false;
  }

  init() {
    if (this.ready) {
      if (this.ctx?.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    try {
      this.ctx = new AudioCtx();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      this.master.connect(this.ctx.destination);

      // Desert wind bed.
      const wind = this.ctx.createBufferSource();
      wind.buffer = this.noiseBuffer(3);
      wind.loop = true;
      const windFilter = this.ctx.createBiquadFilter();
      windFilter.type = 'lowpass';
      windFilter.frequency.value = 260;
      windFilter.Q.value = 0.5;
      this.windGain = this.ctx.createGain();
      this.windGain.gain.value = 0.035;
      wind.connect(windFilter).connect(this.windGain).connect(this.master);
      wind.start();

      // Drill rumble: oscillator + filtered noise.
      this.drillGain = this.ctx.createGain();
      this.drillGain.gain.value = 0;
      this.drillGain.connect(this.master);

      this.drillOsc = this.ctx.createOscillator();
      this.drillOsc.type = 'sawtooth';
      this.drillOsc.frequency.value = 43;
      const drillFilter = this.ctx.createBiquadFilter();
      drillFilter.type = 'lowpass';
      drillFilter.frequency.value = 170;
      const oscGain = this.ctx.createGain();
      oscGain.gain.value = 0.15;
      this.drillOsc.connect(drillFilter).connect(oscGain).connect(this.drillGain);
      this.drillOsc.start();

      const drillNoise = this.ctx.createBufferSource();
      drillNoise.buffer = this.noiseBuffer(2);
      drillNoise.loop = true;
      const noiseFilter = this.ctx.createBiquadFilter();
      noiseFilter.type = 'bandpass';
      noiseFilter.frequency.value = 310;
      noiseFilter.Q.value = 0.8;
      this.drillNoiseGain = this.ctx.createGain();
      this.drillNoiseGain.gain.value = 0.1;
      drillNoise.connect(noiseFilter).connect(this.drillNoiseGain).connect(this.drillGain);
      drillNoise.start();

      this.ready = true;
    } catch {
      this.ready = false;
    }
  }

  noiseBuffer(seconds) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.5;
    }
    return buffer;
  }

  setDrill(on) {
    if (!this.ready) return;
    const now = this.ctx.currentTime;
    this.drillGain.gain.cancelScheduledValues(now);
    this.drillGain.gain.setTargetAtTime(on ? 0.16 : 0, now, on ? 0.18 : 0.25);
    if (this.drillOsc) this.drillOsc.frequency.setTargetAtTime(on ? 47 : 43, now, 0.2);
  }

  setMuted(muted) {
    this.muted = muted;
    if (!this.ready) return;
    this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.08);
  }

  tone(freq, duration = 0.12, type = 'sine', volume = 0.08, delay = 0) {
    if (!this.ready || this.muted) return;
    const now = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(volume, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain).connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.02);
  }

  click() {
    this.tone(700, 0.045, 'square', 0.025);
  }

  pour() {
    this.tone(180, 0.28, 'sine', 0.07);
    this.tone(250, 0.2, 'triangle', 0.035, 0.05);
  }

  buy() {
    this.tone(620, 0.1, 'triangle', 0.05);
    this.tone(880, 0.16, 'triangle', 0.045, 0.08);
  }

  upgrade() {
    [440, 554, 659, 880].forEach((f, i) => this.tone(f, 0.2, 'triangle', 0.05, i * 0.07));
  }

  milestone() {
    [196, 294, 392].forEach((f, i) => this.tone(f, 0.5, 'sine', 0.06, i * 0.12));
  }

  victory() {
    [262, 330, 392, 523, 659].forEach((f, i) => this.tone(f, 0.8, 'sine', 0.075, i * 0.15));
  }

  error() {
    this.tone(130, 0.14, 'square', 0.045);
  }
}

import * as THREE from '../../vendor/three.module.js';

export function canvasTexture(width, height, draw, repeat) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  if (repeat) {
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(repeat[0], repeat[1]);
  }
  return texture;
}

export function dirtTexture() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, '#87694d');
    grad.addColorStop(0.5, '#775c43');
    grad.addColorStop(1, '#6b523d');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 5200; i++) {
      const x = Math.random() * w;
      const y = Math.random() * h;
      const r = Math.random() * 2.2 + 0.2;
      const light = Math.random() > 0.52;
      ctx.fillStyle = light
        ? `rgba(210,176,132,${Math.random() * 0.18})`
        : `rgba(42,29,22,${Math.random() * 0.2})`;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 26; i++) {
      ctx.strokeStyle = '#4d3728';
      ctx.lineWidth = Math.random() * 1.6 + 0.3;
      ctx.beginPath();
      let x = Math.random() * w;
      let y = Math.random() * h;
      ctx.moveTo(x, y);
      for (let j = 0; j < 5; j++) {
        x += (Math.random() - 0.5) * 40;
        y += (Math.random() - 0.5) * 24;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }, [30, 30]);
}

export function concreteTexture() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#6f716c';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 4300; i++) {
      const v = Math.random() * 50 + 45;
      ctx.fillStyle = `rgba(${v},${v},${v - 3},${Math.random() * 0.3})`;
      ctx.fillRect(Math.random() * w, Math.random() * h, Math.random() * 2 + 0.4, Math.random() * 2 + 0.4);
    }
    ctx.strokeStyle = 'rgba(35,35,32,0.35)';
    ctx.lineWidth = 2;
    for (let i = 1; i < 4; i++) {
      ctx.beginPath();
      ctx.moveTo(i * w / 4, 0);
      ctx.lineTo(i * w / 4, h);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * h / 4);
      ctx.lineTo(w, i * h / 4);
      ctx.stroke();
    }
  }, [4, 4]);
}

export function rustTexture() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#793c29';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 3400; i++) {
      const x = Math.random() * w;
      const y = Math.random() * h;
      const r = Math.random() * 7 + 0.5;
      ctx.fillStyle = Math.random() > 0.45
        ? `rgba(144,72,41,${Math.random() * 0.25})`
        : `rgba(45,24,18,${Math.random() * 0.25})`;
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 0.25;
    for (let i = 0; i < 28; i++) {
      ctx.fillStyle = '#d17943';
      ctx.fillRect(Math.random() * w, Math.random() * h, Math.random() * 3 + 1, Math.random() * 45 + 5);
    }
    ctx.globalAlpha = 1;
  }, [3, 2]);
}

export function makeSignTexture(title, subtitle, accent = '#ffb347') {
  return canvasTexture(768, 256, (ctx, w, h) => {
    ctx.fillStyle = '#0b1117';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(255,255,255,0.16)';
    ctx.lineWidth = 4;
    ctx.strokeRect(8, 8, w - 16, h - 16);
    ctx.fillStyle = accent;
    ctx.fillRect(28, 32, 8, h - 64);
    ctx.fillStyle = '#eef4f4';
    ctx.font = '700 66px "Chakra Petch", sans-serif';
    ctx.fillText(title, 62, 110);
    ctx.fillStyle = accent;
    ctx.font = '600 24px "Space Grotesk", sans-serif';
    ctx.letterSpacing = '7px';
    ctx.fillText(subtitle, 64, 160);
    ctx.fillStyle = 'rgba(255,255,255,0.14)';
    ctx.fillRect(64, 186, w - 128, 3);
    ctx.fillStyle = 'rgba(255,255,255,0.45)';
    ctx.font = '500 18px "Space Grotesk", sans-serif';
    ctx.fillText('SITE 07  ·  DEEP BORE DIVISION', 64, 218);
  });
}

export function makeScreenTexture(title, rows, accent = '#72e7ff') {
  return canvasTexture(768, 384, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, '#07131a');
    grad.addColorStop(1, '#0a1c22');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(114,231,255,0.18)';
    ctx.lineWidth = 2;
    for (let x = 0; x < w; x += 48) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y < h; y += 48) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    ctx.fillStyle = accent;
    ctx.font = '700 28px "Chakra Petch", sans-serif';
    ctx.fillText(title, 30, 50);
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.font = '500 19px "Space Grotesk", sans-serif';
    rows.forEach((row, i) => ctx.fillText(row, 30, 98 + i * 31));
    ctx.strokeStyle = accent;
    ctx.globalAlpha = 0.5;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(30, h - 62);
    for (let i = 0; i < 16; i++) {
      ctx.lineTo(30 + i * 44, h - 62 + Math.sin(i * 1.4) * 16);
    }
    ctx.stroke();
    ctx.globalAlpha = 1;
  });
}

export function makeGlowTexture() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    grad.addColorStop(0, 'rgba(255,255,255,1)');
    grad.addColorStop(0.18, 'rgba(255,213,150,0.9)');
    grad.addColorStop(0.48, 'rgba(255,115,48,0.25)');
    grad.addColorStop(1, 'rgba(255,80,20,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  });
}

export function makeDustTexture() {
  return canvasTexture(64, 64, (ctx, w, h) => {
    const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    grad.addColorStop(0, 'rgba(255,235,205,0.9)');
    grad.addColorStop(0.35, 'rgba(255,215,165,0.35)');
    grad.addColorStop(1, 'rgba(255,200,140,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  });
}

export function makeHazardTexture() {
  return canvasTexture(512, 64, (ctx, w, h) => {
    ctx.fillStyle = '#17191a';
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#f3b33f';
    for (let x = -h; x < w + h; x += 52) {
      ctx.beginPath();
      ctx.moveTo(x, h);
      ctx.lineTo(x + 26, h);
      ctx.lineTo(x + 26 + h, 0);
      ctx.lineTo(x + h, 0);
      ctx.closePath();
      ctx.fill();
    }
  }, [3, 1]);
}

import * as THREE from '../../vendor/three.module.js';

export function box(parent, material, w, h, d, x, y, z, shadow = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  mesh.castShadow = shadow;
  mesh.receiveShadow = shadow;
  parent.add(mesh);
  return mesh;
}

export function cylinder(parent, material, radiusTop, radiusBottom, height, segments, x, y, z) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}

export function beamBetween(parent, material, a, b, radius = 0.12, segments = 6) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const length = dir.length();
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, length, segments), material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}

export function addCollider(list, minX, maxX, minZ, maxZ) {
  list.push({ minX, maxX, minZ, maxZ });
}

export function makeLabel(texture, width, height, x, y, z, rotationY = 0, basic = true) {
  const material = basic
    ? new THREE.MeshBasicMaterial({ map: texture, transparent: true, side: THREE.DoubleSide, toneMapped: false })
    : new THREE.MeshStandardMaterial({ map: texture, emissiveMap: texture, emissive: 0xffffff, emissiveIntensity: 0.65, roughness: 0.6, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(width, height), material);
  mesh.position.set(x, y, z);
  mesh.rotation.y = rotationY;
  return mesh;
}

export function lcg(seed = 1) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

