import {
  UPGRADE_DEFS, SHOP_ITEMS, formatMoney, formatDepth, formatClock,
} from './config.js';

const $ = (selector) => document.querySelector(selector);

export class GameUI {
  constructor(handlers = {}) {
    this.handlers = handlers;
    this.modalOpen = false;
    this.modalKind = null;
    this.started = false;
    this.pointerLocked = false;
    this.isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.last = {};
    this.waypointEls = {
      lab: $('.wp-lab'),
      shop: $('.wp-shop'),
      rig: $('.wp-rig'),
    };

    this.el = {
      hud: $('#hud'),
      intro: $('#intro'),
      modal: $('#modal'),
      modalCard: $('#modalCard'),
      victory: $('#victory'),
      fade: $('#fade'),
      depthValue: $('#depthValue'),
      depthFill: $('#depthFill'),
      biomeTag: $('#biomeTag'),
      cashValue: $('#cashValue'),
      cashRate: $('#cashRate'),
      missionTitle: $('#missionTitle'),
      missionCopy: $('#missionCopy'),
      missionMeta: $('#missionMeta'),
      missionPct: $('#missionPct'),
      oilTime: $('#oilTime'),
      oilFill: $('#oilFill'),
      oilInventory: $('#oilInventory'),
      oilMax: $('#oilMax'),
      rigStatus: $('#rigStatus'),
      reticle: $('#reticle'),
      prompt: $('#interactPrompt'),
      promptText: $('#interactText'),
      toastStack: $('#toastStack'),
      clickLook: $('#clickLook'),
      soundToggle: $('#soundToggle'),
      mapZone: $('#mapZone'),
      minimap: $('#minimap'),
      waypointLayer: $('#waypointLayer'),
      touchUI: $('#touchUI'),
      touchUse: $('#touchUse'),
      touchSprint: $('#touchSprint'),
      joystick: $('#joystick'),
      stick: $('#stick'),
      startBtn: $('#startBtn'),
      againBtn: $('#againBtn'),
      victoryTime: $('#victoryTime'),
      victoryEarned: $('#victoryEarned'),
      victoryBarrels: $('#victoryBarrels'),
      victoryUpgrades: $('#victoryUpgrades'),
    };

    this.el.startBtn.addEventListener('click', () => {
      this.handlers.onStart?.();
    });
    this.el.againBtn.addEventListener('click', () => {
      this.handlers.onRestart?.();
    });
    this.el.soundToggle.addEventListener('click', () => {
      this.handlers.onToggleSound?.();
    });
    this.el.modal.addEventListener('click', (event) => {
      if (event.target === this.el.modal) this.handlers.onClosePanel?.();
    });
    this.el.modalCard.addEventListener('click', (event) => {
      const close = event.target.closest('[data-close]');
      if (close) {
        this.handlers.onClosePanel?.();
        return;
      }
      const buy = event.target.closest('[data-buy]');
      if (buy) {
        this.handlers.onBuy?.(buy.dataset.buy);
        return;
      }
      const upgrade = event.target.closest('[data-upgrade]');
      if (upgrade) {
        this.handlers.onUpgrade?.(upgrade.dataset.upgrade);
      }
    });

    if (this.isTouch) {
      this.el.touchUI.style.display = 'block';
      this.el.touchUse.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        this.handlers.onTouchUse?.();
      });
      this.el.touchSprint.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        this.handlers.onSprintToggle?.();
      });
    }
  }

  start() {
    this.started = true;
    this.el.intro.classList.add('hidden');
    this.el.hud.classList.remove('hidden');
  }

  resetToIntro() {
    this.started = false;
    this.modalOpen = false;
    this.el.modal.classList.add('hidden');
    this.el.victory.classList.add('hidden');
    this.el.hud.classList.add('hidden');
    this.el.intro.classList.remove('hidden');
  }

  setPointerLocked(locked) {
    this.pointerLocked = locked;
    this.el.clickLook.classList.toggle('visible', this.started && !locked && !this.modalOpen && !this.isTouch);
  }

  setMuted(muted) {
    this.el.soundToggle.textContent = muted ? 'SOUND OFF' : 'SOUND ON';
  }

  updateHUD(state, info) {
    const {
      biome, objective, rate, tankCapacity, speed, oilSeconds, totalOilSeconds,
    } = info;
    const depth = state.depth;
    const pct = Math.min(100, (depth / 6371) * 100);

    this.setText('depthValue', formatDepth(depth));
    this.el.depthFill.style.width = `${pct}%`;
    this.el.biomeTag.textContent = biome.id;
    this.el.biomeTag.style.color = biome.css;
    this.el.biomeTag.style.borderColor = `${biome.css}66`;
    this.el.biomeTag.style.background = `${biome.css}14`;
    this.setText('cashValue', formatMoney(state.cash));
    this.setText('cashRate', state.drilling ? `+${formatMoney(rate)} / SEC` : '+$0 / SEC');
    this.setText('missionTitle', objective.title);
    this.setText('missionCopy', objective.copy);
    this.setText('missionMeta', objective.meta);
    this.setText('missionPct', `${pct.toFixed(1)}%`);

    const oilPct = Math.min(100, (oilSeconds / Math.max(1, totalOilSeconds)) * 100);
    this.el.oilFill.style.width = `${oilPct}%`;
    this.setText('oilTime', oilSeconds > 0 ? formatClock(oilSeconds) : 'DRY');
    this.setText('oilInventory', `${state.oilInv} BARREL${state.oilInv === 1 ? '' : 'S'}`);
    this.setText('oilMax', `CAPACITY ${tankCapacity} BARREL${tankCapacity === 1 ? '' : 'S'} · ${speed.toFixed(1)} KM/S`);
    const status = this.el.rigStatus;
    status.className = `status ${state.drilling ? 'drilling' : oilSeconds > 0 ? 'ready' : 'idle'}`;
    status.innerHTML = `<i></i>${state.drilling ? 'DRILLING' : oilSeconds > 0 ? 'READY' : 'IDLE'}`;

    if (state.cash !== this.last.cash) {
      this.el.cashValue.animate(
        [{ transform: 'scale(1)' }, { transform: 'scale(1.06)' }, { transform: 'scale(1)' }],
        { duration: 180, easing: 'ease-out' }
      );
      this.last.cash = state.cash;
    }

    this.el.clickLook.classList.toggle('visible', this.started && !this.pointerLocked && !this.modalOpen && !this.isTouch);
  }

  setText(key, value) {
    if (this.last[key] === value) return;
    this.last[key] = value;
    const node = this.el[key];
    if (node) node.textContent = value;
  }

  setInteract(label) {
    if (label) {
      this.el.promptText.textContent = label;
      this.el.prompt.classList.add('visible');
      this.el.reticle.classList.add('active');
    } else {
      this.el.prompt.classList.remove('visible');
      this.el.reticle.classList.remove('active');
    }
  }

  toast(message, type = '') {
    const node = document.createElement('div');
    node.className = `toast ${type}`.trim();
    node.textContent = message;
    this.el.toastStack.appendChild(node);
    while (this.el.toastStack.children.length > 4) this.el.toastStack.firstChild.remove();
    setTimeout(() => {
      node.classList.add('out');
      setTimeout(() => node.remove(), 320);
    }, 2900);
  }

  showModal(kind, state) {
    this.modalOpen = true;
    this.modalKind = kind;
    this.el.modal.classList.remove('hidden');
    this.el.clickLook.classList.remove('visible');
    if (kind === 'shop') this.renderShop(state);
    else this.renderLab(state);
  }

  hideModal() {
    this.modalOpen = false;
    this.modalKind = null;
    this.el.modal.classList.add('hidden');
  }

  renderShop(state) {
    const items = SHOP_ITEMS.map((item) => {
      const affordable = state.cash >= item.cost;
      return `
        <article class="shop-item">
          <div class="item-icon">${item.icon}</div>
          <div class="item-name">${item.name}</div>
          <div class="item-desc">${item.desc}</div>
          <div class="item-stock">+${item.barrels} BARREL${item.barrels === 1 ? '' : 'S'} · IN STOCK</div>
          <button class="buy-btn" data-buy="${item.id}" ${affordable ? '' : 'disabled'}>
            BUY · ${formatMoney(item.cost)}
          </button>
        </article>
      `;
    }).join('');

    this.el.modalCard.innerHTML = `
      <div class="modal-head">
        <div>
          <div class="modal-kicker">OIL DEPOT · SITE 07</div>
          <div class="modal-title">FUEL &amp; SUPPLIES</div>
          <div class="modal-sub">Crude barrels keep the BORE-01 reservoir running. Each barrel burns for exactly 60 seconds of drilling.</div>
        </div>
        <button class="modal-close" data-close aria-label="Close">×</button>
      </div>
      <div class="modal-body">
        <div class="shop-grid">${items}</div>
      </div>
      <div class="modal-foot">
        <span>INVENTORY · ${state.oilInv} BARREL${state.oilInv === 1 ? '' : 'S'}</span>
        <span>AVAILABLE <b class="wallet">${formatMoney(state.cash)}</b></span>
      </div>
    `;
  }

  renderLab(state) {
    const cards = UPGRADE_DEFS.map((def) => {
      const level = state.lv[def.id] || 0;
      const maxed = level >= def.max;
      const cost = maxed ? null : def.costs[level];
      const affordable = cost !== null && state.cash >= cost;
      const pips = Array.from({ length: def.max }, (_, i) => `<i class="${i < level ? 'on' : ''}"></i>`).join('');
      const current = def.stat(level);
      const next = maxed ? null : def.stat(level + 1);
      return `
        <article class="upgrade-card ${maxed ? 'maxed' : ''}">
          <div class="upgrade-top">
            <div class="upgrade-name">${def.name}</div>
            <div class="upgrade-level">${maxed ? 'MAXED' : `LV ${level + 1} / ${def.max}`}</div>
          </div>
          <div class="upgrade-desc">${def.desc}</div>
          <div class="upgrade-stat">${def.statLabel} <b>${current}</b>${next ? `<span>→</span><b>${next}</b>` : ''}</div>
          <div class="level-pips">${pips}</div>
          <button class="buy-btn" data-upgrade="${def.id}" ${maxed || !affordable ? 'disabled' : ''}>
            ${maxed ? 'FULLY UPGRADED' : `INSTALL · ${formatMoney(cost)}`}
          </button>
        </article>
      `;
    }).join('');

    this.el.modalCard.innerHTML = `
      <div class="modal-head">
        <div>
          <div class="modal-kicker">CORE LAB · GEOSCIENCE</div>
          <div class="modal-title">DRILL RESEARCH</div>
          <div class="modal-sub">Spend bore credits on permanent rig improvements. Every upgrade applies immediately to BORE-01.</div>
        </div>
        <button class="modal-close" data-close aria-label="Close">×</button>
      </div>
      <div class="modal-body">
        <div class="upgrade-grid">${cards}</div>
      </div>
      <div class="modal-foot">
        <span>LAB ACCESS · GRANTED</span>
        <span>AVAILABLE <b class="wallet">${formatMoney(state.cash)}</b></span>
      </div>
    `;
  }

  updateWaypoints(camera, zone, waypoints) {
    const show = this.started && zone === 'surface' && !this.modalOpen;
    for (const [key, node] of Object.entries(this.waypointEls)) {
      if (!show) {
        node.classList.remove('visible');
        continue;
      }
      const world = waypoints[key];
      const projected = world.clone().project(camera);
      if (projected.z > 1 || projected.z < -1) {
        node.classList.remove('visible');
        continue;
      }
      const x = (projected.x * 0.5 + 0.5) * window.innerWidth;
      const y = (-projected.y * 0.5 + 0.5) * window.innerHeight;
      if (x < -80 || x > window.innerWidth + 80 || y < -80 || y > window.innerHeight + 80) {
        node.classList.remove('visible');
        continue;
      }
      const dist = world.distanceTo(camera.position);
      node.style.left = `${x}px`;
      node.style.top = `${y}px`;
      node.querySelector('.wp-dist').textContent = `${Math.round(dist)} M`;
      node.classList.add('visible');
    }
  }

  drawMinimap(state, zone, playerPos, yaw) {
    const canvas = this.el.minimap;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    ctx.fillStyle = 'rgba(9,17,22,0.82)';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(114,231,255,0.12)';
    ctx.lineWidth = 1;
    for (let i = 1; i < 5; i++) {
      ctx.beginPath();
      ctx.moveTo((w / 5) * i, 0);
      ctx.lineTo((w / 5) * i, h);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, (h / 5) * i);
      ctx.lineTo(w, (h / 5) * i);
      ctx.stroke();
    }

    const mapX = (x) => ((x + 48) / 96) * w;
    const mapY = (z) => ((z + 54) / 90) * h;

    if (zone === 'surface') {
      this.el.mapZone.textContent = 'SITE 07 · SURFACE';
      // Paths.
      ctx.strokeStyle = 'rgba(176,140,104,0.32)';
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(mapX(0), mapY(28));
      ctx.lineTo(mapX(0), mapY(-15));
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(mapX(0), mapY(-2));
      ctx.lineTo(mapX(-19), mapY(-8));
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(mapX(0), mapY(-2));
      ctx.lineTo(mapX(19), mapY(-8));
      ctx.stroke();

      // Buildings.
      ctx.fillStyle = 'rgba(114,231,255,0.5)';
      ctx.fillRect(mapX(-25), mapY(-12.8), mapX(-13) - mapX(-25), mapY(-3.3) - mapY(-12.8));
      ctx.fillStyle = 'rgba(255,179,71,0.55)';
      ctx.fillRect(mapX(13), mapY(-12.8), mapX(25) - mapX(13), mapY(-3.3) - mapY(-12.8));
      // Rig.
      ctx.strokeStyle = '#ff9c50';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(mapX(0), mapY(-22), 8, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = 'rgba(255,100,40,0.5)';
      ctx.beginPath();
      ctx.arc(mapX(0), mapY(-22), 3.5, 0, Math.PI * 2);
      ctx.fill();

      // Player.
      const px = mapX(playerPos.x);
      const py = mapY(playerPos.z);
      ctx.save();
      ctx.translate(px, py);
      ctx.rotate(-yaw);
      ctx.fillStyle = '#eef4f4';
      ctx.beginPath();
      ctx.moveTo(0, -6);
      ctx.lineTo(4.5, 5);
      ctx.lineTo(0, 3);
      ctx.lineTo(-4.5, 5);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      ctx.strokeStyle = 'rgba(255,255,255,0.16)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(px, py, 13, 0, Math.PI * 2);
      ctx.stroke();
    } else if (zone === 'lab') {
      this.el.mapZone.textContent = 'CORE LAB · INTERIOR';
      ctx.strokeStyle = 'rgba(114,231,255,0.45)';
      ctx.lineWidth = 2;
      ctx.strokeRect(w * 0.16, h * 0.14, w * 0.68, h * 0.72);
      ctx.fillStyle = 'rgba(114,231,255,0.5)';
      ctx.beginPath();
      ctx.arc(w * 0.5, h * 0.46, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,179,71,0.7)';
      ctx.fillRect(w * 0.24, h * 0.26, 12, 5);
      const lx = ((playerPos.x - 193) / 14) * (w * 0.68) + w * 0.16;
      const ly = ((playerPos.z + 6) / 12) * (h * 0.72) + h * 0.14;
      ctx.save();
      ctx.translate(lx, ly);
      ctx.rotate(-yaw);
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.moveTo(0, -5);
      ctx.lineTo(4, 4);
      ctx.lineTo(-4, 4);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    } else {
      this.el.mapZone.textContent = 'OIL DEPOT · INTERIOR';
      ctx.strokeStyle = 'rgba(255,179,71,0.45)';
      ctx.lineWidth = 2;
      ctx.strokeRect(w * 0.16, h * 0.14, w * 0.68, h * 0.72);
      ctx.fillStyle = 'rgba(255,179,71,0.65)';
      ctx.fillRect(w * 0.3, h * 0.38, w * 0.4, 8);
      const sx = ((playerPos.x + 206.5) / 13) * (w * 0.68) + w * 0.16;
      const sy = ((playerPos.z + 5.5) / 11) * (h * 0.72) + h * 0.14;
      ctx.save();
      ctx.translate(sx, sy);
      ctx.rotate(-yaw);
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.moveTo(0, -5);
      ctx.lineTo(4, 4);
      ctx.lineTo(-4, 4);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
  }

  showVictory(stats) {
    this.el.victory.classList.remove('hidden');
    this.el.hud.classList.add('hidden');
    this.el.victoryTime.textContent = stats.time;
    this.el.victoryEarned.textContent = stats.earned;
    this.el.victoryBarrels.textContent = stats.barrels;
    this.el.victoryUpgrades.textContent = stats.upgrades;
  }

  hideVictory() {
    this.el.victory.classList.add('hidden');
    this.el.hud.classList.remove('hidden');
  }

  fade(on) {
    this.el.fade.classList.toggle('on', on);
  }
}

import * as THREE from '../vendor/three.module.js';
import {
  CORE_DEPTH, OIL_SECONDS, BASE_SPEED, START_CASH, SHOP_ITEMS, UPGRADE_DEFS,
  biomeFor, biomeIndex, speedMultiplier, yieldValue, tankMax,
  formatMoney, formatClock,
} from './config.js';
import { createSurface } from './world/surface.js';
import { createInteriors } from './world/interiors.js';
import { SoundEngine } from './audio.js';
import { GameUI } from './ui.js';

const canvas = document.querySelector('#game');

/* ------------------------------------------------------------------ */
/* Renderer / scene                                                    */
/* ------------------------------------------------------------------ */
let renderer;
try {
  renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    powerPreference: 'high-performance',
  });
} catch (error) {
  document.body.innerHTML = '<div style="color:#fff;font:16px sans-serif;padding:40px">WebGL is required to play CORE//BOUND.</div>';
  throw error;
}
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1820);
scene.fog = new THREE.Fog(0xb97855, 62, 275);

const camera = new THREE.PerspectiveCamera(72, window.innerWidth / window.innerHeight, 0.08, 560);
camera.rotation.order = 'YXZ';

const surface = createSurface(scene);
const interiors = createInteriors(scene);

/* ------------------------------------------------------------------ */
/* State                                                              */
/* ------------------------------------------------------------------ */
const state = {
  started: false,
  ending: false,
  cash: START_CASH,
  oilInv: 1,
  rigOil: 0,
  depth: 0,
  drilling: false,
  lv: { motor: 0, refinery: 0, tank: 0, auto: 0 },
  zone: 'surface',
  totalEarned: 0,
  barrelsUsed: 0,
  elapsed: 0,
  drillSeconds: 0,
  biomeIdx: 0,
  muted: false,
  autoTimer: 0,
};

const player = {
  pos: new THREE.Vector3(0, 1.7, 13),
  yaw: 0,
  pitch: -0.02,
  bob: 0,
  bobPhase: 0,
  sprintTouch: false,
};

const keys = new Set();
const touchMove = { x: 0, y: 0 };
let currentInteraction = null;
let transitioning = false;
let dragging = false;
let lookTouchId = null;
let lookTouchX = 0;
let lookTouchY = 0;
let joyTouchId = null;
let joyCenter = { x: 0, y: 0 };

const audio = new SoundEngine();

/* ------------------------------------------------------------------ */
/* UI                                                                 */
/* ------------------------------------------------------------------ */
const ui = new GameUI({
  onStart: startGame,
  onClosePanel: closePanel,
  onBuy: buyItem,
  onUpgrade: purchaseUpgrade,
  onRestart: restartGame,
  onToggleSound: toggleSound,
  onTouchUse: interact,
  onSprintToggle: () => {
    player.sprintTouch = !player.sprintTouch;
    ui.el.touchSprint.classList.toggle('active', player.sprintTouch);
  },
});

/* ------------------------------------------------------------------ */
/* Game actions                                                       */
/* ------------------------------------------------------------------ */
function startGame() {
  if (state.started) return;
  state.started = true;
  state.ending = false;
  state.elapsed = 0;
  player.pos.set(0, 1.7, 13);
  player.yaw = 0;
  player.pitch = -0.02;
  ui.start();
  audio.init();
  requestLock();
  setTimeout(() => {
    ui.toast('One barrel in your pack. Load it into the top reservoir of BORE-01.', 'good');
  }, 650);
}

function requestLock() {
  if (ui.isTouch || ui.modalOpen || state.ending) return;
  try {
    const result = renderer.domElement.requestPointerLock?.();
    if (result?.catch) result.catch(() => {});
  } catch {
    /* Drag-to-look remains available. */
  }
}

function toggleSound() {
  state.muted = !state.muted;
  audio.setMuted(state.muted);
  ui.setMuted(state.muted);
  if (!state.muted) audio.click();
}

function computeObjective() {
  const remaining = Math.max(0, CORE_DEPTH - state.depth);
  const meta = `${formatMoney(state.cash)} · ${remaining.toFixed(0)} KM TO CORE`;
  if (state.ending) {
    return { title: 'CORE REACHED', copy: 'BORE-01 has breached the inner core.', meta };
  }
  if (state.drilling) {
    return {
      title: 'DRILL TO THE CORE',
      copy: 'Keep the reservoir wet. Reinvest bore credits at the lab to go faster.',
      meta,
    };
  }
  if (state.rigOil <= 0 && state.oilInv <= 0) {
    return {
      title: 'BUY OIL',
      copy: 'The reservoir is dry. Visit the OIL DEPOT east of the rig and buy a barrel.',
      meta,
    };
  }
  if (state.rigOil <= 0) {
    return {
      title: 'LOAD THE RIG',
      copy: 'Carry a barrel to BORE-01 and load it into the top reservoir.',
      meta,
    };
  }
  return {
    title: 'START THE DRILL',
    copy: 'Use the control console at the base of the rig to engage the drill.',
    meta,
  };
}

function toggleDrill() {
  if (state.drilling) {
    state.drilling = false;
    audio.setDrill(false);
    ui.toast('BORE-01 paused.');
    return;
  }
  if (state.rigOil <= 0) {
    audio.error();
    ui.toast('Reservoir dry. Load oil at the rig first.', 'warn');
    return;
  }
  state.drilling = true;
  state.autoTimer = 0;
  audio.setDrill(true);
  audio.click();
  ui.toast('BORE-01 engaged. Drilling credits incoming.', 'good');
}

function loadBarrel(auto = false) {
  const cap = tankMax(state) * OIL_SECONDS;
  if (state.oilInv <= 0) {
    audio.error();
    if (!auto) ui.toast('No barrels in your pack. Buy oil at the depot.', 'warn');
    return false;
  }
  if (state.rigOil >= cap - 0.5) {
    audio.error();
    if (!auto) ui.toast('Top reservoir is already full.', 'warn');
    return false;
  }
  state.oilInv -= 1;
  state.rigOil = Math.min(cap, state.rigOil + OIL_SECONDS);
  state.barrelsUsed += 1;
  surface.pulseOil();
  audio.pour();
  ui.toast(auto ? 'Auto-Loader primed a fresh barrel. +60 seconds.' : 'Barrel loaded into the top reservoir. +60 seconds.', 'good');
  if (auto) {
    state.drilling = true;
    audio.setDrill(true);
  }
  return true;
}

function openPanel(kind) {
  if (state.ending) return;
  audio.click();
  document.exitPointerLock?.();
  ui.showModal(kind, state);
}

function closePanel() {
  if (!ui.modalOpen) return;
  ui.hideModal();
  audio.click();
  requestLock();
}

function buyItem(id) {
  const item = SHOP_ITEMS.find((entry) => entry.id === id);
  if (!item) return;
  if (state.cash < item.cost) {
    audio.error();
    ui.toast('Not enough credits. Drill deeper and earn more.', 'warn');
    return;
  }
  state.cash -= item.cost;
  state.oilInv += item.barrels;
  audio.buy();
  ui.toast(`${item.name} purchased. +${item.barrels} barrel${item.barrels === 1 ? '' : 's'}.`, 'good');
  ui.showModal('shop', state);
}

function purchaseUpgrade(id) {
  const def = UPGRADE_DEFS.find((entry) => entry.id === id);
  if (!def) return;
  const level = state.lv[id] || 0;
  if (level >= def.max) return;
  const cost = def.costs[level];
  if (state.cash < cost) {
    audio.error();
    ui.toast('Not enough credits for that installation.', 'warn');
    return;
  }
  state.cash -= cost;
  state.lv[id] = level + 1;
  audio.upgrade();
  ui.toast(`${def.name} upgraded to level ${level + 1}.`, 'good');
  ui.showModal('lab', state);
}

function enterZone(zone) {
  if (transitioning) return;
  transitioning = true;
  audio.click();
  ui.fade(true);
  setTimeout(() => {
    state.zone = zone;
    const spawn = zone === 'lab' ? interiors.labSpawn : interiors.shopSpawn;
    player.pos.copy(spawn.position);
    player.yaw = spawn.yaw;
    player.pitch = spawn.pitch;
    player.bob = 0;
    ui.fade(false);
    transitioning = false;
    ui.toast(zone === 'lab' ? 'CORE LAB · research terminal online.' : 'OIL DEPOT · cashier ready.', 'good');
  }, 280);
}

function leaveZone() {
  if (transitioning) return;
  transitioning = true;
  const exit = state.zone === 'lab' ? interiors.labExit : interiors.shopExit;
  ui.fade(true);
  audio.click();
  setTimeout(() => {
    state.zone = 'surface';
    player.pos.copy(exit.position);
    player.yaw = exit.yaw;
    player.pitch = exit.pitch;
    player.bob = 0;
    ui.fade(false);
    transitioning = false;
    ui.toast('Back on the surface.');
  }, 280);
}

function reachCore() {
  if (state.ending) return;
  state.depth = CORE_DEPTH;
  state.drilling = false;
  state.ending = true;
  state.rigOil = Math.max(0, state.rigOil);
  audio.setDrill(false);
  audio.victory();
  document.exitPointerLock?.();
  ui.setInteract(null);
  ui.toast('CORE BREACH · 6,371 KM. The drill is through.', 'good');
  setTimeout(() => {
    ui.showVictory({
      time: formatClock(state.elapsed),
      earned: formatMoney(state.totalEarned),
      barrels: String(state.barrelsUsed),
      upgrades: String(Object.values(state.lv).reduce((a, b) => a + b, 0)),
    });
  }, 1100);
}

function restartGame() {
  state.ending = false;
  state.started = true;
  state.cash = START_CASH;
  state.oilInv = 1;
  state.rigOil = 0;
  state.depth = 0;
  state.drilling = false;
  state.lv = { motor: 0, refinery: 0, tank: 0, auto: 0 };
  state.zone = 'surface';
  state.totalEarned = 0;
  state.barrelsUsed = 0;
  state.elapsed = 0;
  state.drillSeconds = 0;
  state.biomeIdx = 0;
  state.autoTimer = 0;
  player.pos.set(0, 1.7, 13);
  player.yaw = 0;
  player.pitch = -0.02;
  player.bob = 0;
  ui.hideVictory();
  ui.setMuted(state.muted);
  surface.setDepth(0, biomeFor(0));
  audio.setDrill(false);
  requestLock();
  ui.toast('New expedition. One barrel in your pack.', 'good');
}

function interact() {
  if (!state.started || state.ending || ui.modalOpen || transitioning) return;
  if (!currentInteraction) return;
  currentInteraction.action();
}

/* ------------------------------------------------------------------ */
/* Input                                                              */
/* ------------------------------------------------------------------ */
window.addEventListener('keydown', (event) => {
  const code = event.code;
  if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ShiftLeft', 'ShiftRight'].includes(code)) {
    keys.add(code);
    if (code.startsWith('Arrow')) event.preventDefault();
  }
  if (code === 'KeyE') {
    event.preventDefault();
    interact();
  }
  if (code === 'Escape') {
    if (ui.modalOpen) {
      closePanel();
    }
  }
  if (code === 'KeyM') toggleSound();
});

window.addEventListener('keyup', (event) => {
  keys.delete(event.code);
});

window.addEventListener('blur', () => {
  keys.clear();
  player.sprintTouch = false;
});

renderer.domElement.addEventListener('mousedown', (event) => {
  if (event.button !== 0) return;
  if (!state.started || ui.modalOpen || state.ending) return;
  if (document.pointerLockElement !== renderer.domElement) {
    dragging = true;
    requestLock();
  }
});
window.addEventListener('mouseup', () => { dragging = false; });

window.addEventListener('mousemove', (event) => {
  if (!state.started || ui.modalOpen || state.ending) return;
  if (document.pointerLockElement !== renderer.domElement && !dragging) return;
  player.yaw -= event.movementX * 0.00215;
  player.pitch -= event.movementY * 0.00215;
  player.pitch = Math.max(-1.35, Math.min(1.35, player.pitch));
});

document.addEventListener('pointerlockchange', () => {
  ui.setPointerLocked(document.pointerLockElement === renderer.domElement);
});
document.addEventListener('pointerlockerror', () => {
  ui.setPointerLocked(false);
});

// Touch look.
renderer.domElement.addEventListener('pointerdown', (event) => {
  if (!ui.isTouch || !state.started || ui.modalOpen || state.ending) return;
  if (lookTouchId !== null) return;
  lookTouchId = event.pointerId;
  lookTouchX = event.clientX;
  lookTouchY = event.clientY;
  renderer.domElement.setPointerCapture?.(event.pointerId);
});
window.addEventListener('pointermove', (event) => {
  if (event.pointerId !== lookTouchId) return;
  const dx = event.clientX - lookTouchX;
  const dy = event.clientY - lookTouchY;
  lookTouchX = event.clientX;
  lookTouchY = event.clientY;
  player.yaw -= dx * 0.0042;
  player.pitch -= dy * 0.0042;
  player.pitch = Math.max(-1.35, Math.min(1.35, player.pitch));
});
window.addEventListener('pointerup', (event) => {
  if (event.pointerId === lookTouchId) lookTouchId = null;
  if (event.pointerId === joyTouchId) resetJoystick();
});

// Virtual joystick.
function updateJoystick(event) {
  const max = 42;
  let dx = event.clientX - joyCenter.x;
  let dy = event.clientY - joyCenter.y;
  const len = Math.hypot(dx, dy);
  if (len > max) {
    dx = (dx / len) * max;
    dy = (dy / len) * max;
  }
  touchMove.x = dx / max;
  touchMove.y = -dy / max;
  ui.el.stick.style.transform = `translate(${dx}px, ${dy}px)`;
}
function resetJoystick() {
  joyTouchId = null;
  touchMove.x = 0;
  touchMove.y = 0;
  ui.el.stick.style.transform = 'translate(0px, 0px)';
}
ui.el.joystick.addEventListener('pointerdown', (event) => {
  if (!ui.isTouch) return;
  event.preventDefault();
  const rect = ui.el.joystick.getBoundingClientRect();
  joyCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
  joyTouchId = event.pointerId;
  ui.el.joystick.setPointerCapture?.(event.pointerId);
  updateJoystick(event);
});
ui.el.joystick.addEventListener('pointermove', (event) => {
  if (event.pointerId !== joyTouchId) return;
  event.preventDefault();
  updateJoystick(event);
});

/* ------------------------------------------------------------------ */
/* Movement / collision                                               */
/* ------------------------------------------------------------------ */
function colliders() {
  if (state.zone === 'lab') return interiors.labColliders;
  if (state.zone === 'shop') return interiors.shopColliders;
  return surface.colliders;
}

function collides(x, z) {
  const radius = 0.38;
  if (state.zone === 'surface') {
    if (x < -39.5 || x > 39.5 || z < -46 || z > 28.5) return true;
    const hx = x - surface.hole.x;
    const hz = z - surface.hole.z;
    if (Math.hypot(hx, hz) < surface.hole.radius + radius) return true;
  }
  for (const c of colliders()) {
    if (x + radius > c.minX && x - radius < c.maxX && z + radius > c.minZ && z - radius < c.maxZ) {
      return true;
    }
  }
  return false;
}

function updatePlayer(dt) {
  if (!state.started || state.ending || ui.modalOpen || transitioning) {
    player.bob *= 0.9;
    return;
  }
  let forwardInput = 0;
  let rightInput = 0;
  if (keys.has('KeyW') || keys.has('ArrowUp')) forwardInput += 1;
  if (keys.has('KeyS') || keys.has('ArrowDown')) forwardInput -= 1;
  if (keys.has('KeyD') || keys.has('ArrowRight')) rightInput += 1;
  if (keys.has('KeyA') || keys.has('ArrowLeft')) rightInput -= 1;
  forwardInput += touchMove.y;
  rightInput += touchMove.x;

  const length = Math.hypot(forwardInput, rightInput);
  if (length > 1) {
    forwardInput /= length;
    rightInput /= length;
  }

  const sprint = keys.has('ShiftLeft') || keys.has('ShiftRight') || player.sprintTouch;
  const speed = sprint ? 7.4 : 4.6;
  const forward = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
  const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  const move = new THREE.Vector3()
    .addScaledVector(forward, forwardInput)
    .addScaledVector(right, rightInput)
    .multiplyScalar(speed * dt);

  if (Math.abs(move.x) > 0.0001) {
    const nx = player.pos.x + move.x;
    if (!collides(nx, player.pos.z)) player.pos.x = nx;
  }
  if (Math.abs(move.z) > 0.0001) {
    const nz = player.pos.z + move.z;
    if (!collides(player.pos.x, nz)) player.pos.z = nz;
  }

  const moving = Math.abs(forwardInput) + Math.abs(rightInput) > 0.05;
  if (moving) {
    player.bobPhase += dt * (sprint ? 12.5 : 8.5);
    player.bob += (Math.sin(player.bobPhase) * 0.035 - player.bob) * Math.min(1, dt * 12);
  } else {
    player.bob += (0 - player.bob) * Math.min(1, dt * 9);
  }
}

/* ------------------------------------------------------------------ */
/* Drilling                                                           */
/* ------------------------------------------------------------------ */
function updateDrill(dt) {
  if (!state.started || state.ending || ui.modalOpen) return;

  if (state.drilling) {
    if (state.rigOil <= 0) {
      state.drilling = false;
      audio.setDrill(false);
      return;
    }
    const used = Math.min(dt, state.rigOil);
    state.rigOil = Math.max(0, state.rigOil - used);
    state.drillSeconds += dt;

    const speed = BASE_SPEED * speedMultiplier(state);
    const delta = Math.min(speed * dt, CORE_DEPTH - state.depth);
    state.depth += delta;
    const earned = delta * yieldValue(state);
    state.cash += earned;
    state.totalEarned += earned;

    const newBiome = biomeIndex(state.depth);
    if (newBiome !== state.biomeIdx) {
      state.biomeIdx = newBiome;
      const biome = biomeFor(state.depth);
      audio.milestone();
      ui.toast(`ENTERING ${biome.id} · ${biome.name}`, 'good');
    }

    if (state.depth >= CORE_DEPTH - 0.001) {
      reachCore();
      return;
    }

    if (state.rigOil <= 0.001) {
      state.rigOil = 0;
      state.drilling = false;
      state.autoTimer = 0;
      audio.setDrill(false);
      ui.toast('Reservoir dry. BORE-01 has stopped.', 'warn');
    }
  }

  // Auto-loader quality-of-life upgrade.
  if (state.lv.auto > 0 && !state.drilling && state.rigOil <= 0 && state.oilInv > 0 && !state.ending) {
    state.autoTimer += dt;
    if (state.autoTimer > 1.4) {
      state.autoTimer = 0;
      if (loadBarrel(true)) {
        state.drilling = true;
        audio.setDrill(true);
      }
    }
  } else if (state.drilling) {
    state.autoTimer = 0;
  }
}

/* ------------------------------------------------------------------ */
/* Interaction                                                        */
/* ------------------------------------------------------------------ */
function interactionList() {
  if (state.zone === 'lab') {
    return [
      {
        id: 'lab-terminal',
        pos: interiors.labInteractables.terminal,
        radius: 3.1,
        label: 'Access research terminal',
        action: () => openPanel('lab'),
      },
      {
        id: 'lab-exit',
        pos: interiors.labInteractables.exit,
        radius: 3.0,
        label: 'Exit to surface',
        action: leaveZone,
      },
    ];
  }
  if (state.zone === 'shop') {
    return [
      {
        id: 'shop-counter',
        pos: interiors.shopInteractables.counter,
        radius: 3.4,
        label: 'Open oil depot shop',
        action: () => openPanel('shop'),
      },
      {
        id: 'shop-exit',
        pos: interiors.shopInteractables.exit,
        radius: 3.0,
        label: 'Exit to surface',
        action: leaveZone,
      },
    ];
  }

  const cap = tankMax(state) * OIL_SECONDS;
  const oilFull = state.rigOil >= cap - 0.5;
  return [
    {
      id: 'rig-oil',
      pos: surface.interactables.oil,
      radius: 4.2,
      label: oilFull ? 'Top reservoir full' : state.oilInv > 0 ? 'Load oil into top reservoir' : 'No barrels · buy oil at depot',
      action: () => loadBarrel(false),
    },
    {
      id: 'rig-console',
      pos: surface.interactables.console,
      radius: 3.3,
      label: state.drilling ? 'Stop the drill' : state.rigOil > 0 ? 'Start the drill' : 'Reservoir dry · load oil first',
      action: toggleDrill,
    },
    {
      id: 'lab-door',
      pos: surface.interactables.labDoor,
      radius: 3.2,
      label: 'Enter CORE LAB',
      action: () => enterZone('lab'),
    },
    {
      id: 'shop-door',
      pos: surface.interactables.shopDoor,
      radius: 3.2,
      label: 'Enter OIL DEPOT',
      action: () => enterZone('shop'),
    },
  ];
}

function updateInteraction() {
  if (!state.started || state.ending || ui.modalOpen || transitioning) {
    currentInteraction = null;
    ui.setInteract(null);
    return;
  }
  const forward = new THREE.Vector3();
  camera.getWorldDirection(forward);
  let best = null;
  let bestScore = -Infinity;
  for (const item of interactionList()) {
    const to = item.pos.clone().sub(camera.position);
    const distance = to.length();
    if (distance > item.radius) continue;
    const dot = forward.dot(to.normalize());
    if (dot < 0.08) continue;
    const score = dot * 2 - distance / item.radius;
    if (score > bestScore) {
      bestScore = score;
      best = item;
    }
  }
  currentInteraction = best;
  ui.setInteract(best ? best.label : null);
}

/* ------------------------------------------------------------------ */
/* Camera / intro                                                     */
/* ------------------------------------------------------------------ */
function updateCamera(time) {
  if (!state.started) {
    camera.position.set(0, 1.9 + Math.sin(time * 0.22) * 0.025, 13.8);
    camera.rotation.set(-0.015 + Math.sin(time * 0.17) * 0.005, Math.sin(time * 0.1) * 0.012, 0, 'YXZ');
    return;
  }
  camera.position.set(player.pos.x, 1.7 + player.bob, player.pos.z);
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ');
}

/* ------------------------------------------------------------------ */
/* Main loop                                                          */
/* ------------------------------------------------------------------ */
let lastTime = performance.now();
let hudAccumulator = 0;
let mapAccumulator = 0;
let lastDepthForWorld = -1;

function animate(now) {
  requestAnimationFrame(animate);
  const dt = Math.min(0.05, Math.max(0.001, (now - lastTime) / 1000));
  lastTime = now;
  const time = now / 1000;

  if (state.started && !state.ending && !ui.modalOpen) {
    state.elapsed += dt;
    updatePlayer(dt);
    updateDrill(dt);
    updateInteraction();
  } else if (!state.started) {
    updatePlayer(dt);
  }

  updateCamera(time);
  surface.setDepth(state.depth, biomeFor(state.depth));
  surface.update(dt, time, state);
  interiors.update(dt, time);

  hudAccumulator += dt;
  if (hudAccumulator > 0.08) {
    hudAccumulator = 0;
    const biome = biomeFor(state.depth);
    ui.updateHUD(state, {
      biome,
      objective: computeObjective(),
      rate: state.drilling ? BASE_SPEED * speedMultiplier(state) * yieldValue(state) : 0,
      tankCapacity: tankMax(state),
      speed: BASE_SPEED * speedMultiplier(state),
      oilSeconds: state.rigOil,
      totalOilSeconds: tankMax(state) * OIL_SECONDS,
    });
    ui.updateWaypoints(camera, state.zone, surface.waypoints);
  }

  mapAccumulator += dt;
  if (mapAccumulator > 0.12) {
    mapAccumulator = 0;
    ui.drawMinimap(state, state.zone, player.pos, player.yaw);
  }

  renderer.render(scene, camera);
}

/* ------------------------------------------------------------------ */
/* Resize                                                             */
/* ------------------------------------------------------------------ */
function resize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
  renderer.setSize(window.innerWidth, window.innerHeight);
}
window.addEventListener('resize', resize);

// Small quality-of-life: pause the drill while the tab is hidden.
document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    keys.clear();
    player.sprintTouch = false;
    ui.el.touchSprint.classList.remove('active');
  }
});

/* ------------------------------------------------------------------ */
/* Debug hook (used for visual QA; harmless in normal play)           */
/* ------------------------------------------------------------------ */
window.__CORE__ = {
  state,
  player,
  ui,
  start: startGame,
  addCash: (amount) => { state.cash += amount; },
  setDepth: (depth) => { state.depth = Math.max(0, Math.min(CORE_DEPTH, depth)); },
  teleport: (x, z, yaw = 0) => { player.pos.set(x, 1.7, z); player.yaw = yaw; },
  enterZone,
  leaveZone,
  openPanel,
  loadBarrel,
  toggleDrill,
  reachCore,
};

surface.setDepth(0, biomeFor(0));
ui.setMuted(false);
ui.drawMinimap(state, state.zone, player.pos, player.yaw);
requestAnimationFrame(animate);

